  { const n = px.x.length, Sx = px.x.reduce((a, b) => a + b), Sy = px.y.reduce((a, b) => a + b), Sxy = px.x.reduce((a, v, i) => a + v * px.y[i], 0), Sxx = px.x.reduce((a, v) => a + v * v, 0); px.a = (n * Sxy - Sx * Sy) / (n * Sxx - Sx * Sx); px.b0 = (Sy - px.a * Sx) / n; px.pe = px.d / px.a; px.res = Math.sqrt(px.y.reduce((s, y, i) => s + (y - px.a * px.x[i] - px.b0) ** 2, 0) / (n - 2)); }
