  const by = { pri: [0.3, 0.5, 0.2], lik: [0.05, 0.2, 0.95] }; by.num = by.pri.map((p, i) => p * by.lik[i]); by.sum = by.num.reduce((a, b) => a + b); by.post = by.num.map(v => v / by.sum);
  const lr = { prior: 0.2, LR: 19 }; lr.po = lr.prior / (1 - lr.prior) * lr.LR; lr.post = lr.po / (1 + lr.po);
  const r3 = { p: 0.01, C: 0.95 }; r3.n = Math.log(1 - r3.C) / Math.log(1 - r3.p); const inter = { lam: 0.1, T: 2 }; inter.P = 1 - Math.exp(-inter.lam * inter.T); inter.T95 = -Math.log(0.05) / inter.lam; const dem = { M: 1000 }; dem.T = -dem.M * Math.log(1 - 0.95);
  const PB1 = { R: 1e6 }; PB1.dmm = measCalc(PB1.R, MEAS3.inst.dmm[0]); PB1.x1 = measCalc(PB1.R, MEAS3.inst.x1[0]); PB1.an = measCalc(PB1.R, MEAS3.inst.an[0]);
  const PB2 = { V: 8, I: 2, r: 0.5 }; PB2.x = PB2.V / (PB2.I * PB2.r);
  const E1 = Math.ceil(Math.log2(200)), E2 = 1 - Math.exp(-0.5), E3 = 3 / 0.001;

  const sections = [
    tbSec('27.1', 'למדוד לפני שמפרקים', `
      <p><b>המודל.</b> שלוש המדידות הראשונות, בסדר: התנגדות של כל פס הזנה לאדמה בלי מתח, מתחי ההזנה עם מתח, ורק אז כל השאר. אבל כל מדידה גם נוגעת. מכשיר עם <bdi>R<sub>m</sub></bdi> על נקודה במחלק של שני נגדים <bdi>R</bdi> מקבל במקביל לנגד התחתון <bdi>R<sub>p</sub> = R ∥ R<sub>m</sub></bdi>:</p>
      ${tbEq('27.1', 'V<sub>m</sub> = V<sub>s</sub> · R<sub>p</sub> / (R + R<sub>p</sub>)   ,   R<sub>p</sub> = R R<sub>m</sub> / (R + R<sub>m</sub>)')}
      ${tbEq('27.2', 'ε = V<sub>m</sub> / V<sub>t</sub> − 1')}
      <p><b>הפיתוח: הדלקה מוגבלת.</b> כרטיס חשוד מדליקים מספק עם הגבלת זרם <bdi>I<sub>lim</sub></bdi>. אם יש קצר, ההספק שנכנס אליו חסום:</p>
      ${tbEq('27.3', 'P<sub>max</sub> = V · I<sub>lim</sub>')}
      <p>ובלי מתח, משווים התנגדות של כל פס לאותו פס בכרטיס תקין. קצר נראה כיחס גדול:</p>
      ${tbEq('27.4', 'r = R<sub>good</sub> / R<sub>meas</sub>   ,   r ≫ 1 ⇒ קצר')}
      <p><b>פרשנות.</b> הדלקה ישירה של כרטיס עם קצר שורפת עוד רכיבים ומוחקת את העדויות. ומדידה בנקודה עם התנגדות גבוהה צריכה מכשיר גבוה ממנה בהרבה: אחרת המכשיר יוצר את התקלה שמחפשים.</p>
      <div class="tb-ex"><p class="tb-exh">דוגמה 27.1</p><p>מחלק של <bdi>100 kΩ</bdi> בכל צד ו-<bdi>10 V</bdi>, מולטימטר של <bdi>10 MΩ</bdi>: לפי 27.1, <bdi>${tbN(l0.Vm, 3)} V</bdi>, ולפי 27.2: <bdi>${tbN(l0.err * 100, 2)}%</bdi>. מד מחוגים של <bdi>200 kΩ</bdi>: <bdi>${tbN(lan.Vm, 2)} V</bdi>, <bdi>${tbN(lan.err * 100, 0)}%</bdi>. ספק של <bdi>${pu.V} V</bdi> מוגבל ל-<bdi>${pu.I} A</bdi>, לפי 27.3: <bdi>${tbN(pu.P, 1)} W</bdi> לכל היותר. פס של <bdi>${rail.bad} Ω</bdi> מול <bdi>${rail.good / 1000} kΩ</bdi> בכרטיס תקין, לפי 27.4: יחס של <bdi>${tbN(rail.good / rail.bad, 0)}</bdi>.</p></div>
      ${tbFig([['3d:loading', 'מדידה היא נגיעה: המכשיר מעמיס'], ['f:meas', 'נוסחאות מדידה'], ['p:lab/s-wire', 'מעבדת כבל וחיבור']], 'מגדילים את הנגדים ומחליפים מכשיר, ורואים את הקריאה יורדת מתחת לאמת.')}`),
    tbSec('27.2', 'בידוד: חצי-חצי, קצר בפס ונקודה חמה', `
      <p><b>המודל.</b> כשהתקלה באחד מ-<bdi>N</bdi> חלקים, מחלקים לשניים, בודקים איזה חצי, וחוזרים. מספר הבדיקות:</p>
      ${tbEq('27.5', 'n = ⌈ log<sub>2</sub> N ⌉')}
      <p><b>הפיתוח: איפה הקצר בפס.</b> מזרימים זרם ידוע <bdi>I</bdi> בפס הנחושת עם התנגדות <bdi>r</bdi> ליחידת אורך, ומודדים את המפל בין תחילת הפס לנקודת הקצר. בשיטת מיליאוהם:</p>
      ${tbEq('27.6', 'x = ΔV / (I · r)')}
      <p>ואם יש מתח, הקצר מתחמם: הספק <bdi>I²R</bdi>, והטמפרטורה עולה לפי ההתנגדות התרמית שלו (26.2). מצלמה תרמית, או אצבע זהירה, מוצאת את הנקודה:</p>
      ${tbEq('27.7', 'ΔT = I² R<sub>short</sub> · R<sub>th</sub>')}
      <p>ומדידה שנראית "מוזרה" משווים לפיזור של כרטיסים תקינים, ולא לתחושה:</p>
      ${tbEq('27.8', 'z = (x − μ<sub>good</sub>) / σ<sub>good</sub>')}
      <p><b>פרשנות.</b> חצי-חצי עובד כשהשרשרת ליניארית וכשאפשר לנתק. בכרטיס עם פס אחד שמזין עשרים רכיבים, מנתקים רכיבים לפי הסדר מהרחוק לקרוב, או מוצאים את החם. ומשווים תמיד לכרטיס תקין: "10 kΩ" לבד לא אומר כלום.</p>
      <div class="tb-ex"><p class="tb-exh">דוגמה 27.2</p><p><bdi>${bs.N}</bdi> חלקים, לפי 27.5: <bdi>${bs.n}</bdi> בדיקות. פס עם <bdi>${mo.r} mΩ/mm</bdi>, <bdi>${mo.I} A</bdi> ומפל של <bdi>${mo.V} mV</bdi>, לפי 27.6: <bdi>${tbN(mo.x, 0)} mm</bdi> מהקצה. קצר של <bdi>${hot.R} Ω</bdi> עם <bdi>${hot.I} A</bdi> ו-<bdi>${hot.Rth} K/W</bdi>, לפי 27.7: <bdi>${tbN(hot.dT, 0)} °C</bdi>. פס שמודד <bdi>${z.x} kΩ</bdi> כשהתקינים <bdi>${z.m} ± ${z.s} kΩ</bdi>, לפי 27.8: <bdi>z = ${tbN(z.z, 2)}</bdi>, חשוד.</p></div>
      ${tbFig([['s:card', 'כרטיס I/O: נקודות מדידה'], ['3d:input', 'כרטיס קלט 24 V בתלת-ממד'], ['p:brd/fa', 'חקר כשל בכרטיס']], 'מזריקים תקלה ומחפשים אותה: קודם התנגדות בלי מתח, אחר כך מתחים.')}`),
    tbSec('27.3', 'מסקנה ודוח: מה סביר, ומה מוכח', `
      <p><b>המודל.</b> לכל תסמין כמה סיבות אפשריות. לפני שבודקים יש לכל אחת סבירות מוקדמת <bdi>P(C<sub>i</sub>)</bdi>, מניסיון ומסטטיסטיקה של תקלות. מדידה <bdi>S</bdi> מעדכנת אותן לפי בייס:</p>
      ${tbEq('27.9', 'P(C<sub>i</sub> | S) = P(S | C<sub>i</sub>) P(C<sub>i</sub>) / Σ<sub>j</sub> P(S | C<sub>j</sub>) P(C<sub>j</sub>)')}
      <p><b>הפיתוח: יחס סבירות.</b> כשיש שתי השערות, נוח יותר בסיכויים (odds). כל מדידה מכפילה אותם ביחס הסבירות שלה:</p>
      ${tbEq('27.10', 'O<sub>post</sub> = O<sub>prior</sub> · LR   ,   LR = P(S | C) / P(S | ¬C)')}
      <p>מדידה טובה היא מדידה עם LR רחוק מ-1: היא מפרידה בין ההשערות. מדידה שתוצאתה צפויה בכל ההשערות לא מוסיפה מידע, גם אם היא קלה.</p>
      <p><b>פרשנות.</b> דוח טוב כותב את התסמין, המדידות לפי הסדר עם הערכים, ההשערות שנפסלו ולמה, הסיבה, התיקון, והאימות אחרי התיקון. ומבדיל בין מה שנמדד לבין מה שמשוער. מי שקורא אותו צריך להיות מסוגל לחזור על הבדיקה ולקבל אותה תוצאה.</p>
      <div class="tb-ex"><p class="tb-exh">דוגמה 27.3</p><p>כרטיס מת. סבירות מוקדמת: פיוז <bdi>${by.pri[0]}</bdi>, מייצב <bdi>${by.pri[1]}</bdi>, קצר בפס <bdi>${by.pri[2]}</bdi>. מדידה: פס ההזנה <bdi>2 Ω</bdi> לאדמה. הסבירות של זה בכל סיבה: <bdi>${by.lik.join(', ')}</bdi>. לפי 27.9: <bdi>${by.post.map(p => tbN(p, 2)).join(', ')}</bdi>. קצר בפס עלה מ-<bdi>${by.pri[2]}</bdi> ל-<bdi>${tbN(by.post[2], 2)}</bdi>.</p>
        <p>בסיכויים, לפי 27.10: מ-<bdi>${lr.prior}</bdi> עם <bdi>LR = ${lr.LR}</bdi>, <bdi>${tbN(lr.post, 2)}</bdi>.</p></div>
      ${tbFig([['3d:bringup', 'הפעלה ראשונה בתלת-ממד: שלב אחר שלב'], ['t:bringup:fault:drop', 'תקלה: נפילת מתח'], ['p:int/field', 'בשטח']], 'עוברים שלב אחר שלב, וכותבים ליד כל שלב מה נמדד ומה זה פסל.')}`),
    tbSec('27.4', 'פיתוח מתקדם: מתי מותר לומר "תוקן"', `
      <p><b>אפס כשלים ב-n ניסיונות.</b> אם הסיכוי לכשל בניסיון הוא <bdi>p</bdi>, הסיכוי לא לראות אף אחד ב-<bdi>n</bdi>:</p>
      ${tbEq('27.11', 'P<sub>0</sub> = (1 − p)<sup>n</sup>')}
      <p>כדי לטעון בביטחון <bdi>C</bdi> שהקצב קטן מ-<bdi>p</bdi>, דורשים <bdi>P<sub>0</sub> ≤ 1 − C</bdi>:</p>
      ${tbEq('27.12', 'n = ln(1 − C) / ln(1 − p)   ≈   3/p')}
      <p>להראות שקצב הכשל קטן מ-1% בביטחון של 95%: <bdi>${tbN(Math.ceil(r3.n), 0)}</bdi> ניסיונות. זה "כלל השלוש".</p>
      <p><b>תקלה לסירוגין.</b> תקלה שמופיעה בקצב <bdi>λ</bdi> נתפסת בבדיקה באורך <bdi>T</bdi> בסיכוי:</p>
      ${tbEq('27.13', 'P<sub>catch</sub> = 1 − e<sup>−λT</sup>')}
      <p>פעם בעשר שעות, ובדיקה של שעתיים: <bdi>${tbN(inter.P * 100, 0)}%</bdi>. ל-95% צריך <bdi>${tbN(inter.T95, 0)}</bdi> שעות.</p>
      ${tbEq('27.14', 'T<sub>95</sub> = −ln(0.05) / λ ≈ 3/λ')}
      <p>וכדי להדגים MTBF של <bdi>M</bdi> בלי כשל אחד, באותו היגיון:</p>
      ${tbEq('27.15', 'T = −M · ln(1 − C)')}
      <p><bdi>${dem.M} h</bdi> ב-95%: <bdi>${tbN(dem.T, 0)} h</bdi>. "עבד שעה בלי בעיה" לא מוכיח שתקלה של פעם ביום תוקנה.</p>`, true)
  ];
